    from collections import deque

    h, w = len(grid), len(grid[0])

    counts = Counter()
    for row in grid:
        counts.update(row)

    if len(counts) == 1:
        return grid

    bg = max(counts, key=counts.get)
    fg = [c for c in counts if c != bg][0]

    result = [[0] * w for _ in range(h)]
    visited = [[False] * w for _ in range(h)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(i, j):
        group = []
        q = deque([(i, j)])
        visited[i][j] = True
        group.append((i, j))
        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == fg:
                    visited[nr][nc] = True
                    group.append((nr, nc))
                    q.append((nr, nc))
        return group

    for i in range(h):
        for j in range(w):
            if not visited[i][j] and grid[i][j] == fg:
                group = bfs(i, j)
                size = len(group)

                # Check if linear (only horizontal or only vertical)
                r_coords = sorted({r for r,c in group})
                c_coords = sorted({c for r,c in group})

                is_horizontal_line = (len(r_coords) == 1 and size >= 2)
                is_vertical_line = (len(c_coords) == 1 and size >= 2)

                if size == 1:
                    code = 1
                elif size == 2:
                    if is_horizontal_line:
                        code = 2
                    elif is_vertical_line:
                        code = 3
                    else:
                        code = 1
                else:
                    code = 1

                for r, c in group:
                    result[r][c] = code

    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg:
                result[i][j] = bg

    return result
